vector<pair<int, int>> theSolve(int n, int m) {
  if (m == 1 || m == 2 || m == 4 || m == 6) {
    return {};
  }
  if (m == 12) {
    vector<pair<int, int>> e;
    for (int x = 1; x <= 6; x++) {
      for (int y = x + 1; y <= 6; y++) {
        if (max(x, y) >= 4) {
          e.pb({x, y});
        }
      }
    }
    return e;
  }
  if (n == 6 && m == 11) {
    return {{1, 2},
            {1, 3},
            {2, 4},
            {2, 5},
            {2, 6},
            {3, 4},
            {3, 5},
            {3, 6},
            {4, 5},
            {4, 6},
            {5, 6}};
  }
  if (n == 8 && m == 22) {
    vector<pair<int, int>> e;
    for (int v = 1; v <= 7; v++) {
      for (int u = v + 1; u <= 7; u++) {
        e.pb({v, u});
      }
    }
    e.pb({7, 8});
    return e;
  }
  if (n == 10 && m == 39) {
    vector<pair<int, int>> e;
    for (int x = 1; x <= n - 1; x++) {
      for (int y = x + 1; y <= n - 1; y++) {
        e.pb({x, y});
      }
    }
    for (int x = 1; x <= 3; x++) {
      e.pb({n, x});
    }
    return e;
  }
  vector<pair<int, int>> edges;
  if (n % 2 == 1) {
    while (m <= (n - 2) * (n - 3) / 2) {
      n -= 2;
    }
    int q = (2 * m) / n, r = (2 * m) % n;
    if (q % 2 == 0) {
      for (int v = 0; v < n; v++) {
        for (int p = 0; p < q / 2; p++) {
          int u = (v + 1 + p) % n;
          edges.pb({v + 1, u + 1});
        }
      }
      for (int v = 0; v < r / 2; v++) {
        edges.pb({v + 1, (v + n / 2) % n + 1});
      }
    } else {
      int d = (n - r) / 2;
      for (int v = 0; v < n; v++) {
        for (int p = 0; p < (q + 1) / 2; p++) {
          if (v % 2 == 0 && p == 0 && d) {
            d--;
            continue;
          }
          int u = (v + 1 + p) % n;
          edges.pb({v + 1, u + 1});
        }
      }
    }
    return edges;
  }

  int rest = n * (n - 1) / 2 - m;
  if (rest == 0 || rest == 1 || rest == 2 || rest == 4 || rest == 6) {
    return {};
  }
  if (m <= (n - 1) * (n - 2) / 2) {
    return theSolve(n - 1, m);
  }
  vector<pair<int, int>> inv_e = theSolve(n - 1, n * (n - 1) / 2 - m);
  for (auto &p : inv_e) {
    if (p.first > p.second) {
      swap(p.first, p.second);
    }
  }
  sort(all(inv_e));
  int i = 0;
  vector<pair<int, int>> e;
  for (int v = 1; v <= n; v++) {
    for (int u = v + 1; u <= n; u++) {
      if (i < (int) inv_e.size() && inv_e[i] == (pair<int, int>) {v, u}) {
        i++;
        continue;
      }
      e.pb({v, u});
    }
  }
  return e;
}

